<script setup lang="ts">
import {computed,ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {useCoffee} from '../stores/coffee';import {money,localTime,localDate,createVietQrPayload} from '../../../../packages/shared/src/domain';import QRCode from 'qrcode';import Icon from '../components/Icon.vue';
const s=useCoffee();const route=useRoute();const order=computed(()=>s.state.orders.find(o=>o.id===route.params.id));const width=ref('80');const qr=ref('');
onMounted(async()=>{if(!order.value)return;const i=s.state.intents.filter(i=>i.orderId===order.value!.id).at(-1);if(i&&i.amount===order.value.total-order.value.paid&&i.amount>0)qr.value=await QRCode.toDataURL(createVietQrPayload(i.bank,i.amount,i.reference),{width:250,margin:3})});
function print(){window.print()}
</script><template><div class="receipt-page"><header class="receipt-toolbar"><RouterLink class="btn outline" to="/pos"><Icon name="back"/>Về bán hàng</RouterLink><label>Khổ giấy <select v-model="width" aria-label="Khổ giấy bill"><option value="80">80 mm</option><option value="58">58 mm</option></select></label><button class="btn primary" @click="print" :disabled="!order"><Icon name="printer"/>In bill</button></header><article v-if="order" class="thermal-receipt" :style="{width:width+'mm'}"><img v-if="s.state.settings.logo" :src="s.state.settings.logo" alt="Logo quán" class="receipt-logo"><h1>{{s.state.settings.name}}</h1><p>{{s.state.branches.find(b=>b.id===order!.branchId)?.address}}</p><p v-if="s.state.settings.phone">{{s.state.settings.phone}}</p><hr><h2>Bill bán hàng</h2><p>{{order.number}} · {{order.tableName}}</p><p>{{localDate(order.createdAt)}} {{localTime(order.createdAt)}}</p><hr><div v-for="l in order.lines" :key="l.id" class="thermal-line"><b>{{l.name}} ({{l.variant}})</b><small v-if="l.optionNames.length">{{l.optionNames.join(', ')}}</small><small v-if="l.note">{{l.note}}</small><div><span>{{l.quantity}} × {{money(l.unitPrice)}}</span><b>{{money(l.total)}}</b></div></div><hr><div class="total-row"><span>Giảm giá</span><span>{{money(order.discount)}}</span></div><div class="total-row"><span>Phụ thu</span><span>{{money(order.surcharge)}}</span></div><div class="total-row"><strong>Tổng cộng</strong><strong>{{money(order.total)}}</strong></div><div class="total-row"><span>Đã thu</span><span>{{money(order.paid)}}</span></div><div class="total-row"><b>Còn phải thu</b><b>{{money(Math.max(0,order.total-order.paid))}}</b></div><div v-if="order.refunded" class="total-row"><span>Đã hoàn tiền</span><span>{{money(order.refunded)}}</span></div><p class="receipt-status">{{order.paid>=order.total?'Xác nhận đã lưu trên trình duyệt':'Chưa thanh toán'}}</p><img v-if="qr" :src="qr" alt="QR chuyển số tiền còn phải thu" class="qr-image"><hr><p>Cảm ơn bạn đã ghé quán!</p><small>Bill bán hàng không phải hóa đơn điện tử.</small></article><div v-else class="empty"><h2>Không tìm thấy bill trên trình duyệt này</h2><RouterLink to="/pos">Về bán hàng</RouterLink></div><p class="receipt-footnote">In qua hộp thoại trình duyệt. In tự động USB/LAN cần Print Agent được kết nối.</p></div></template>
